html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}
{% if letter_head and not no_letterhead %}
<div class="letter-head">{{ letter_head }}</div>
{% endif %}
{%- endmacro -%}

{% for page in layout %}
<div class="page-break invoice-page">
    <div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
        {{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
    </div>

    <style>
        .invoice-page { font-family: "Source Sans Pro", sans-serif; color: #171717; font-size: 13px; }
        .print-format-body { padding: 0px 12px !important; }
        .title { color: #7c7c7c !important; font-weight: bold; }
        .info-text { margin-bottom: 8px; }
        .text-right { text-align: right; }
        .text-center { text-align: center; }
        .mt-15 { margin-top: 15px; }

        .items-table { width: 100%; border-collapse: collapse; margin-top: 20px; }
        .items-table thead { background-color: #f8f8f8; }
        .items-table td, .items-table th { 
            border: 1px solid #ededed; 
            padding: 10px 8px; 
            vertical-align: middle;
        }
        .items-table th { color: #7c7c7c; font-weight: 500; text-align: left; }

        /* 扫码框样式 */
        .barcode-box { border: 1px solid #eee; padding: 5px; display: inline-block; }
    </style>

    <div class="print-format-body">
        <table style="width: 100%; margin-bottom: 20px;">
            <tr>
                <td style="width: 60%;">
                    <div style="margin-top: 10px;">
                        <span class="title">{{ _("日期") }}:</span> {{ frappe.utils.format_date(doc.transaction_date) }}
                    </div>
                </td>
                <td style="width: 40%; text-align: right; vertical-align: top;">
                    {% if doc.customer %}
                    <div class="info-text">
                        <span class="title">{{ _("客户") }}:</span> {{ doc.customer_name or doc.customer }}
                    </div>
                    {% endif %}
                    <div class="info-text">
                        <span class="title">{{ _("状态") }}:</span> {{ doc.status }}
                    </div>
                </td>
            </tr>
        </table>

        <table class="items-table">
            <thead>
                <tr>
                    <th width="40px" class="text-center">#</th>
                    <th>{{ _("物品代码 / 名称") }}</th>
                    <th>{{ _("源仓库") }}</th>
                    <th class="text-right">{{ _("待拣数量") }}</th>
                    <th class="text-right">{{ _("单位") }}</th>
                    <th width="120px">{{ _("批次/序列号") }}</th>
                    <th width="80px" class="text-center">{{ _("确认") }}</th>
                </tr>
            </thead>
            <tbody>
                {% for item in doc.locations %}
                <tr>
                    <td class="text-center">{{ loop.index }}</td>
                    <td>
                        <div style="font-weight: bold;">{{ item.item_code }}</div>
                        <div style="font-size: 11px; color: #666;">{{ item.item_name }}</div>
                    </td>
                    <td>
                        {{ item.warehouse }}
                    </td>
                    <td class="text-right">
                        <span style="font-size: 16px; font-weight: bold;">{{ item.get_formatted("qty") }}</span>
                    </td>
                    <td class="text-right">{{ item.uom }}</td>
                    <td>
                        {% if item.serial_no %}
                            <div style="font-size: 10px; word-break: break-all;">{{ item.serial_no }}</div>
                        {% elif item.batch_no %}
                            <div>{{ item.batch_no }}</div>
                        {% else %}
                            <span style="color: #ccc;">---</span>
                        {% endif %}
                    </td>
                    <td class="text-center">
                        <div style="border: 1px solid #ccc; width: 20px; height: 20px; display: inline-block;"></div>
                    </td>
                </tr>
                {% endfor %}
            </tbody>
        </table>

        <div class="mt-40" style="margin-top: 50px;">
            <table style="width: 100%;">
                <tr>
                    <td style="width: 50%; vertical-align: top;">
                        {% if doc.remarks %}
                        <div class="title">{{ _("备注") }}:</div>
                        <div style="padding: 5px; border: 1px solid #f0f0f0; min-height: 60px;">{{ doc.remarks }}</div>
                        {% endif %}
                    </td>
                    <td style="width: 50%; text-align: right; vertical-align: bottom;">
                        <div style="display: inline-block; text-align: left;">
                            <div style="border-bottom: 1px solid #000; width: 200px; height: 30px;"></div>
                            <div class="title" style="margin-top: 5px;">{{ _("拣货人签名") }}</div>
                        </div>
                    </td>
                </tr>
            </table>
        </div>
    </div>
</div>
{% endfor %}
